// Host checks for the warm/cold white brightness scaling of CCT buses (WS2805, FW1906, SM16825, WWA).
// The production scaleCct() and CctPixel are spliced in by tools/cct-test.js; no controller is contacted.
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

typedef uint8_t byte;
/* COLOR_MACROS */
/* CCT_PIXEL */
/* SCALE_CCT */

#define CHECK(condition) do { if (!(condition)) throw std::runtime_error(#condition); } while (0)

static const uint32_t WHITE_ONLY = RGBW32(0, 0, 0, 255); // "accurate" auto white turns RGB white into this

static CctPixel scaled(uint8_t ww, uint8_t cw, uint8_t bri, uint32_t c = WHITE_ONLY) {
  CctPixel cct{};
  cct.ww = ww; cct.cw = cw;
  scaleCct(cct, bri, c);
  return cct;
}

int main() {
  const std::vector<std::pair<std::string, std::function<void()>>> cases = {
    {"full brightness leaves the pair untouched", [] {
      for (unsigned ww = 0; ww < 256; ww++) {
        const CctPixel cct = scaled(ww, 255 - ww, 255);
        CHECK(cct.ww == ww && cct.cw == 255 - ww);
      }
    }},
    {"zero brightness is always off", [] {
      CHECK(scaled(255, 255, 0).wwcw == 0);
      CHECK(scaled(1, 0, 0).wwcw == 0);
    }},
    {"every channel is within half a step of the exact value", [] {
      for (unsigned bri = 1; bri < 256; bri++) for (unsigned v = 0; v < 256; v++) {
        const CctPixel cct = scaled(v, 255 - v, bri);
        if (cct.wwcw == 0 || (v * bri < 128 && (255 - v) * bri < 128)) continue; // minimum-light case, checked below
        CHECK(std::abs((int)cct.ww * 255 - (int)(v * bri)) <= 127);
        CHECK(std::abs((int)cct.cw * 255 - (int)((255 - v) * bri)) <= 127);
      }
    }},
    {"the weaker channel survives dimming", [] {
      // the livingroom lamp at night: mostly warm, brightness 5. Truncation gave warm 4, cold 0
      const CctPixel cct = scaled(216, 39, 5);
      CHECK(cct.ww == 4 && cct.cw == 1);
    }},
    {"a white light stays on at the lowest brightness", [] {
      for (unsigned v = 0; v < 256; v++) {
        const CctPixel cct = scaled(v, 255 - v, 1);
        CHECK(cct.ww + cct.cw == 1); // truncation gave 0 for every mix but the two pure ones
        CHECK((cct.ww == 1) == (v >= 128));
      }
    }},
    {"dimming is monotonic per channel", [] {
      for (unsigned v = 0; v < 256; v += 5) {
        CctPixel previous{};
        for (unsigned bri = 0; bri < 256; bri++) {
          const CctPixel cct = scaled(v, 255 - v, bri);
          CHECK(cct.ww >= previous.ww && cct.cw >= previous.cw);
          previous = cct;
        }
      }
    }},
    {"white that is negligible next to the color may dim to zero", [] {
      CHECK(scaled(1, 0, 60, RGBW32(255, 0, 0, 1)).wwcw == 0);   // below half of the brightest RGB channel
      CHECK(scaled(0, 140, 1, RGBW32(255, 0, 0, 140)).cw == 1);  // above it: kept, like color_fade() keeps W
    }},
    {"no white stays no white", [] {
      for (unsigned bri = 0; bri < 256; bri++) CHECK(scaled(0, 0, bri).wwcw == 0);
    }}
  };
  unsigned failures = 0;
  for (const auto& test : cases) {
    try { test.second(); std::cout << "PASS " << test.first << '\n'; }
    catch (const std::exception& error) { failures++; std::cout << "FAIL " << test.first << ": " << error.what() << '\n'; }
  }
  std::cout << cases.size() - failures << '/' << cases.size() << " CCT scaling checks passed\n";
  return failures ? 1 : 0;
}
